1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode"
15		"unicode/utf16"
16		"unicode/utf8"
17	)
18	
19	// Point 是一条序列上某个时间戳的采样值。
20	type Point struct {
21		Timestamp int64   `json:"timestamp"`
22		Value     float64 `json:"value"`
23	}
24	
25	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
26	type SeriesView struct {
27		Name   string            `json:"name"`
28		Labels map[string]string `json:"labels"`
29		Points []Point           `json:"points"`
30	}
31	
32	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
33	type QuerySeries struct {
34		Name    string            `json:"name"`
35		Labels  map[string]string `json:"labels"`
36		Count   int               `json:"count"`
37		Average float64           `json:"average"`
38	}
39	
40	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
41	type QueryResult struct {
42		Status string        `json:"status"`
43		Op     string        `json:"op"`
44		Series []QuerySeries `json:"series"`
45	}
46	
47	// QueryPointsSeries 是采样明细查询结果中的一条序列：完整身份与区间内
48	// 按时间戳升序排列的采样点，不附带点数或平均值。
49	type QueryPointsSeries struct {
50		Name   string            `json:"name"`
51		Labels map[string]string `json:"labels"`
52		Points []Point           `json:"points"`
53	}
54	
55	// QueryPointsResult 是一次区间采样明细查询（op 为 query_points）成功后的结果，
56	// 只读，不改变存储。
57	type QueryPointsResult struct {
58		Status string              `json:"status"`
59		Op     string              `json:"op"`
60		Series []QueryPointsSeries `json:"series"`
61	}
62	
63	// Window 是固定时间窗口统计中的一个窗口：[Start,End] 闭区间（含首尾毫秒）内
64	// 已成功保存的点的个数与算术平均值。空窗口不会出现——只有实际有点的窗口才列出。
65	type Window struct {
66		Start   int64   `json:"start"`
67		End     int64   `json:"end"`
68		Count   int     `json:"count"`
69		Average float64 `json:"average"`
70	}
71	
72	// QueryWindowsSeries 是固定窗口均值查询结果中的一条序列：完整身份与按窗口起点
73	// 升序排列的窗口统计，空窗口不补零。
74	type QueryWindowsSeries struct {
75		Name    string            `json:"name"`
76		Labels  map[string]string `json:"labels"`
77		Windows []Window          `json:"windows"`
78	}
79	
80	// QueryWindowsResult 是一次固定时间窗口均值查询（op 为 query_windows）成功后的
81	// 结果，只读，不改变存储。
82	type QueryWindowsResult struct {
83		Status string               `json:"status"`
84		Op     string               `json:"op"`
85		Series []QueryWindowsSeries `json:"series"`
86	}
87	
88	// BatchResult 是一批采样点写入成功后的结果。
89	type BatchResult struct {
90		Status     string       `json:"status"`
91		Added      int          `json:"added"`
92		Duplicates int          `json:"duplicates"`
93		Series     []SeriesView `json:"series"`
94	}
95	
96	// SeriesRef 标识一条序列：指标名加完整标签集合。
97	// 缺少某个标签与该标签值为空字符串属于不同序列。
98	type SeriesRef struct {
99		Name   string            `json:"name"`
100		Labels map[string]string `json:"labels"`
101	}
102	
103	// Conflict 描述同一序列同一时间戳已存在不同的值。
104	type Conflict struct {
105		Series    SeriesRef `json:"series"`
106		Timestamp int64     `json:"timestamp"`
107		Existing  float64   `json:"existing"`
108		Submitted float64   `json:"submitted"`
109	}
110	
111	// LineError 是一行（一批）输入失败后的结构化结果。
112	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
113	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
114	type LineError struct {
115		Status   string    `json:"status"`
116		Line     int       `json:"line,omitempty"`
117		Index    int       `json:"index,omitempty"`
118		Error    string    `json:"error"`
119		Conflict *Conflict `json:"conflict,omitempty"`
120	}
121	
122	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
123	type MetricStore struct {
124		series map[seriesID]*storedSeries
125	}
126	
127	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
128	type seriesID struct {
129		name string
130		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
131		sig string
132	}
133	
134	type storedSeries struct {
135		ref    SeriesRef
136		points map[int64]float64
137	}
138	
139	// NewMetricStore 创建一个空的指标存储。
140	func NewMetricStore() *MetricStore {
141		return &MetricStore{series: make(map[seriesID]*storedSeries)}
142	}
143	
144	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
145	// 调用方对副本的增删改不影响存储中的序列身份。
146	func cloneLabels(labels map[string]string) map[string]string {
147		out := make(map[string]string, len(labels))
148		for k, v := range labels {
149			out[k] = v
150		}
151		return out
152	}
153	
154	func sortedKeys(m map[string]string) []string {
155		keys := make([]string, 0, len(m))
156		for k := range m {
157			keys = append(keys, k)
158		}
159		sort.Strings(keys)
160		return keys
161	}
162	
163	func makeSeriesID(name string, labels map[string]string) seriesID {
164		var b strings.Builder
165		for _, k := range sortedKeys(labels) {
166			v := labels[k]
167			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
168		}
169		return seriesID{name: name, sig: b.String()}
170	}
171	
172	// labelPair 是标签键值对字典序比较的单元。
173	type labelPair struct {
174		Key, Value string
175	}
176	
177	func sortedPairs(labels map[string]string) []labelPair {
178		keys := sortedKeys(labels)
179		pairs := make([]labelPair, len(keys))
180		for i, k := range keys {
181			pairs[i] = labelPair{Key: k, Value: labels[k]}
182		}
183		return pairs
184	}
185	
186	func compareLabelPairs(a, b []labelPair) int {
187		n := len(a)
188		if len(b) < n {
189			n = len(b)
190		}
191		for i := 0; i < n; i++ {
192			if a[i].Key != b[i].Key {
193				return strings.Compare(a[i].Key, b[i].Key)
194			}
195			if a[i].Value != b[i].Value {
196				return strings.Compare(a[i].Value, b[i].Value)
197			}
198		}
199		switch {
200		case len(a) < len(b):
201			return -1
202		case len(a) > len(b):
203			return 1
204		}
205		return 0
206	}
207	
208	var (
209		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
210		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
211	)
212	
213	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
214	// 成功时返回非 nil 的 *BatchResult、*QueryResult、*QueryPointsResult 或
215	// *QueryWindowsResult 且错误为 nil；任何失败都返回真正的 nil 结果与 *LineError，
216	// 调用方直接比较 result == nil 即可判定失败，无须先区分结果类型。空写入数组与
217	// 无命中的查询仍是成功，结果不为 nil。
218	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
219		top, ok, lerr := decodeTopValue(line)
220		if lerr != nil {
221			return nil, lerr
222		}
223		switch ok {
224		case '[':
225			var items []json.RawMessage
226			if err := json.Unmarshal(top, &items); err != nil {
227				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
228			}
229			// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
230			// 接口值非 nil，调用方会把失败误判为有结果。
231			batch, lerr := s.ingestItems(items)
232			if lerr != nil {
233				return nil, lerr
234			}
235			return batch, nil
236		case '{':
237			// 同上：失败时不能把带类型 nil 的结果指针装进 any。
238			return s.queryFromObject(top)
239		default:
240			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
241		}
242	}
243	
244	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
245	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
246	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
247		top, ok, lerr := decodeTopValue(line)
248		if lerr != nil {
249			return nil, lerr
250		}
251		if ok != '[' {
252			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
253		}
254		var items []json.RawMessage
255		if err := json.Unmarshal(top, &items); err != nil {
256			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
257		}
258		return s.ingestItems(items)
259	}
260	
261	// QueryLine 解析并执行一行 op 为 "query" 的区间均值查询对象。成功返回 QueryResult；
262	// 查询只读，不改变存储。op 为 "query_points" 的采样明细查询由 QueryPointsLine
263	// 执行，op 为 "query_windows" 的固定窗口均值查询由 QueryWindowsLine 执行。
264	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
265		top, ok, lerr := decodeTopValue(line)
266		if lerr != nil {
267			return nil, lerr
268		}
269		if ok != '{' {
270			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
271		}
272		res, lerr := s.queryFromObject(top)
273		if lerr != nil {
274			return nil, lerr
275		}
276		qr, isQuery := res.(*QueryResult)
277		if !isQuery {
278			if _, isPoints := res.(*QueryPointsResult); isPoints {
279				return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
280			}
281			return nil, &LineError{Status: "error", Error: `op "query_windows" lists fixed-window averages; use QueryWindowsLine`}
282		}
283		return qr, nil
284	}
285	
286	// QueryWindowsLine 解析并执行一行 op 为 "query_windows" 的固定时间窗口均值查询
287	// 对象。成功返回 QueryWindowsResult；查询只读，不改变存储。
288	func (s *MetricStore) QueryWindowsLine(line string) (*QueryWindowsResult, *LineError) {
289		top, ok, lerr := decodeTopValue(line)
290		if lerr != nil {
291			return nil, lerr
292		}
293		if ok != '{' {
294			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
295		}
296		res, lerr := s.queryFromObject(top)
297		if lerr != nil {
298			return nil, lerr
299		}
300		qw, isWindows := res.(*QueryWindowsResult)
301		if !isWindows {
302			if _, isPoints := res.(*QueryPointsResult); isPoints {
303				return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
304			}
305			return nil, &LineError{Status: "error", Error: `op "query" computes range statistics; use QueryLine`}
306		}
307		return qw, nil
308	}
309	
310	// QueryPointsLine 解析并执行一行 op 为 "query_points" 的区间采样明细查询对象。
311	// 成功返回 QueryPointsResult；查询只读，不改变存储。
312	func (s *MetricStore) QueryPointsLine(line string) (*QueryPointsResult, *LineError) {
313		top, ok, lerr := decodeTopValue(line)
314		if lerr != nil {
315			return nil, lerr
316		}
317		if ok != '{' {
318			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
319		}
320		res, lerr := s.queryFromObject(top)
321		if lerr != nil {
322			return nil, lerr
323		}
324		qp, isPoints := res.(*QueryPointsResult)
325		if !isPoints {
326			if _, isWindows := res.(*QueryWindowsResult); isWindows {
327				return nil, &LineError{Status: "error", Error: `op "query_windows" lists fixed-window averages; use QueryWindowsLine`}
328			}
329			return nil, &LineError{Status: "error", Error: `op "query" computes range statistics; use QueryLine`}
330		}
331		return qp, nil
332	}
333	
334	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
335	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
336	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
337	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
338	//
339	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
340	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
341	func validateLineText(line string) *LineError {
342		if !utf8.ValidString(line) {
343			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
344		}
345		inString := false
346		for i := 0; i < len(line); i++ {
347			c := line[i]
348			if !inString {
349				if c == '"' {
350					inString = true
351				}
352				continue
353			}
354			switch c {
355			case '"':
356				inString = false
357			case '\\':
358				if i+1 >= len(line) {
359					break // 悬空反斜杠：交给 JSON 解析器报错
360				}
361				if line[i+1] != 'u' {
362					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
363					continue
364				}
365				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
366				r, size := decodeJSONHexEscape(line, i+1)
367				if size == 0 {
368					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
369				}
370				if !utf16.IsSurrogate(r) {
371					i += 5
372					continue
373				}
374				if r >= 0xDC00 {
375					// 单独出现的低代理项。
376					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
377				}
378				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
379				loPos := i + 6 // 第一个转义之后的字符位置
380				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
381					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
382				}
383				lo, loSize := decodeJSONHexEscape(line, loPos+1)
384				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
385					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
386				}
387				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
388			}
389		}
390		return nil
391	}
392	
393	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
394	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
395	func decodeJSONHexEscape(line string, pos int) (rune, int) {
396		if pos+4 >= len(line) {
397			return 0, 0
398		}
399		var v rune
400		for j := pos + 1; j <= pos+4; j++ {
401			c := line[j]
402			var d rune
403			switch {
404			case c >= '0' && c <= '9':
405				d = rune(c - '0')
406			case c >= 'a' && c <= 'f':
407				d = rune(c-'a') + 10
408			case c >= 'A' && c <= 'F':
409				d = rune(c-'A') + 10
410			default:
411				return 0, 0
412			}
413			v = v<<4 | d
414		}
415		return v, 5
416	}
417	
418	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
419	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
420	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
421		if lerr := validateLineText(line); lerr != nil {
422			return nil, 0, lerr
423		}
424		dec := json.NewDecoder(strings.NewReader(line))
425		var top json.RawMessage
426		if err := dec.Decode(&top); err != nil {
427			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
428		}
429		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
430		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
431			if err == nil {
432				err = fmt.Errorf("unexpected content after the JSON value")
433			}
434			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
435		}
436		trimmed := strings.TrimSpace(string(top))
437		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
438			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
439		}
440		return top, trimmed[0], nil
441	}
442	
443	// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
444	// 采样点与查询对象各自注册自己允许的字段及字段含义。
445	type fieldReader func(dec *json.Decoder) error
446	
447	// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
448	// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
449	// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
450	// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
451	// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
452	// 保留各自输入的措辞。
453	func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
454		dec := json.NewDecoder(bytes.NewReader(raw))
455		dec.UseNumber()
456	
457		tok, err := dec.Token()
458		if err != nil {
459			return err
460		}
461		if d, ok := tok.(json.Delim); !ok || d != '{' {
462			return fmt.Errorf("%s", notObjectMsg)
463		}
464	
465		present := make(map[string]bool)
466		for dec.More() {
467			keyTok, err := dec.Token()
468			if err != nil {
469				return err
470			}
471			key := keyTok.(string)
472			read, ok := fields[key]
473			if !ok {
474				return fmt.Errorf("unknown field %q", key)
475			}
476			if present[key] {
477				return fmt.Errorf("duplicate field %q", key)
478			}
479			present[key] = true
480			if err := read(dec); err != nil {
481				return err
482			}
483		}
484		if _, err := dec.Token(); err != nil { // 消耗 '}'
485			return err
486		}
487		if _, err := dec.Token(); err != io.EOF {
488			if err == nil {
489				return fmt.Errorf("%s", trailingMsg)
490			}
491			return err
492		}
493	
494		for _, field := range required {
495			if !present[field] {
496				return fmt.Errorf("missing required field %q", field)
497			}
498		}
499		return nil
500	}
501	
502	// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
503	func readNameField(dec *json.Decoder, dst *string) error {
504		t, err := dec.Token()
505		if err != nil {
506			return err
507		}
508		s, ok := t.(string)
509		if !ok {
510			return fmt.Errorf(`field "name" must be a string`)
511		}
512		if s == "" {
513			return fmt.Errorf(`field "name" must be a non-empty string`)
514		}
515		*dst = s
516		return nil
517	}
518	
519	// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
520	// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
521	func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
522		n, err := nextJSONNumber(dec, field)
523		if err != nil {
524			return err
525		}
526		v, err := parseJSONInt(n)
527		if err != nil {
528			return fmt.Errorf("field %q: %s", field, err)
529		}
530		*dst = v
531		return nil
532	}
533	
534	// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
535	func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
536		n, err := nextJSONNumber(dec, field)
537		if err != nil {
538			return err
539		}
540		v, err := parseFiniteFloat(n)
541		if err != nil {
542			return fmt.Errorf("field %q: %s", field, err)
543		}
544		*dst = v
545		return nil
546	}
547	
548	// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
549	func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
550		labels, err := parseLabels(dec, notObjectMsg)
551		if err != nil {
552			return err
553		}
554		*dst = labels
555		return nil
556	}
557	
558	type parsedSample struct {
559		name   string
560		ts     int64
561		value  float64
562		labels map[string]string
563	}
564	
565	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
566	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
567	func parseSample(raw json.RawMessage) (parsedSample, error) {
568		var p parsedSample
569		p.labels = map[string]string{}
570		err := parseStrictObject(raw,
571			"each sample must be a JSON object",
572			"unexpected content after the sample object",
573			[]string{"name", "timestamp", "value"},
574			map[string]fieldReader{
575				"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
576				"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
577				"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
578				"labels": func(dec *json.Decoder) error {
579					return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
580				},
581			})
582		return p, err
583	}
584	
585	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
586	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
587	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
588	// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
589	// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
590	// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
591	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
592	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
593		t, err := dec.Token()
594		if err != nil {
595			return nil, err
596		}
597		d, ok := t.(json.Delim)
598		if !ok || d != '{' {
599			return nil, fmt.Errorf("%s", notObjectMsg)
600		}
601		labels := map[string]string{}
602		for dec.More() {
603			labelKeyTok, err := dec.Token()
604			if err != nil {
605				return nil, err
606			}
607			labelKey := labelKeyTok.(string)
608			if labelKey == "" {
609				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
610			}
611			// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
612			if _, dup := labels[labelKey]; dup {
613				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
614			}
615			valTok, err := dec.Token()
616			if err != nil {
617				return nil, err
618			}
619			labelVal, ok := valTok.(string)
620			if !ok {
621				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
622			}
623			labels[labelKey] = labelVal
624		}
625		if _, err := dec.Token(); err != nil { // 消耗 '}'
626			return nil, err
627		}
628		return labels, nil
629	}
630	
631	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
632		t, err := dec.Token()
633		if err != nil {
634			return "", err
635		}
636		n, ok := t.(json.Number)
637		if !ok {
638			return "", fmt.Errorf(`field %q must be a JSON number`, field)
639		}
640		return n, nil
641	}
642	
643	func parseJSONInt(n json.Number) (int64, error) {
644		s := string(n)
645		if !jsonIntegerRE.MatchString(s) {
646			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
647		}
648		v, err := strconv.ParseInt(s, 10, 64)
649		if err != nil {
650			return 0, fmt.Errorf("must be within int64 range")
651		}
652		return v, nil
653	}
654	
655	func parseFiniteFloat(n json.Number) (float64, error) {
656		s := string(n)
657		if !jsonNumberRE.MatchString(s) {
658			return 0, fmt.Errorf("must be a JSON number")
659		}
660		v, err := strconv.ParseFloat(s, 64)
661		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
662			return 0, fmt.Errorf("must be a finite number representable as float64")
663		}
664		return v, nil
665	}
666	
667	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
668	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
669		type pending struct {
670			id  seriesID
671			ref SeriesRef
672			ts  int64
673			val float64
674		}
675	
676		added := 0
677		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
678		seen := make(map[seriesID]map[int64]float64)
679		// 仅记录需要落盘的新增点；校验全部通过后才提交。
680		commits := make([]pending, 0, len(items))
681	
682		failAt := func(index int, msg string) *LineError {
683			return &LineError{Status: "error", Index: index, Error: msg}
684		}
685		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
686			return &LineError{
687				Status: "error",
688				Index:  index,
689				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
690					ref, ts, formatFloat(existing), formatFloat(submitted)),
691				Conflict: &Conflict{
692					// 标签必须复制：冲突结果是本次失败的独立记录，
693					// 调用方修改它不能改动已存序列的身份。
694					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
695					Timestamp: ts,
696					Existing:  existing,
697					Submitted: submitted,
698				},
699			}
700		}
701	
702		for i, item := range items {
703			pos := i + 1
704			p, err := parseSample(item)
705			if err != nil {
706				return nil, failAt(pos, err.Error())
707			}
708	
709			id := makeSeriesID(p.name, p.labels)
710			ref := SeriesRef{Name: p.name, Labels: p.labels}
711	
712			// 同一采样位置无论值来自本批较早接受的点还是此前批次已写入的点，
713			// 都走同一条判定：转换后的 float64 相等即重复、成功忽略，不同即冲突、
714			// 整批拒绝。existing 是该位置当前生效的值，两种来源下语义一致。
715			if existing, ok := s.positionValue(seen, id, p.ts); ok {
716				if existing != p.value {
717					return nil, conflictAt(pos, ref, p.ts, existing, p.value)
718				}
719				// 等值重复：成功忽略。seen 记录的是生效值 existing 而不是本次
720				// 提交的 p.value：数值相等但表示不同（如已存 -0、本次提交 +0）时，
721				// 本批后续在同位置的冲突必须如实报告最先接受的值，
722				// 不能被这条被忽略的重复改写。
723				if seen[id] == nil {
724					seen[id] = map[int64]float64{}
725				}
726				seen[id][p.ts] = existing
727				continue
728			}
729	
730			added++
731			if seen[id] == nil {
732				seen[id] = map[int64]float64{}
733			}
734			seen[id][p.ts] = p.value
735			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
736		}
737	
738		// 全部采样点合法且无冲突，原子提交本批新增点。
739		for _, c := range commits {
740			sr := s.series[c.id]
741			if sr == nil {
742				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
743				s.series[c.id] = sr
744			}
745			sr.points[c.ts] = c.val
746		}
747	
748		return s.snapshot(added, len(items)-added), nil
749	}
750	
751	// positionValue 解析一个采样位置（序列身份 + 时间戳）当前生效的值：
752	// 本批已接受的值优先（含与已写入数据等值而被忽略的重复所登记的生效值），
753	// 其次是此前批次已成功写入的值；该位置没有任何数据时 ok 为 false。
754	// 重复与冲突判定只看这里返回的值，不再区分两种来源。
755	func (s *MetricStore) positionValue(seen map[seriesID]map[int64]float64, id seriesID, ts int64) (value float64, ok bool) {
756		if byTS, found := seen[id]; found {
757			if v, hit := byTS[ts]; hit {
758				return v, true
759			}
760		}
761		if sr, found := s.series[id]; found {
762			if v, hit := sr.points[ts]; hit {
763				return v, true
764			}
765		}
766		return 0, false
767	}
768	
769	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
770	func formatFloat(v float64) string {
771		return strconv.FormatFloat(v, 'g', -1, 64)
772	}
773	
774	type parsedQuery struct {
775		op        string
776		name      string
777		start     int64
778		end       int64
779		labels    map[string]string
780		step      int64
781		stepGiven bool
782		// basicGiven 记录 op/name/start/end 四个基础字段是否在对象中出现过：
783		// 必填检查不能用零值判断（0 与空串可能就是合法输入）。
784		basicGiven map[string]bool
785	}
786	
787	// queryFromObject 严格解析查询对象并执行对应的只读操作：op 为 "query" 时
788	// 统计区间内点数与均值，为 "query_points" 时列出区间内采样明细，为
789	// "query_windows" 时按固定宽度时间窗口分别统计点数与均值。
790	// 成功返回非 nil 的 *QueryResult、*QueryPointsResult 或 *QueryWindowsResult；
791	// 失败返回 nil 与 *LineError。
792	func (s *MetricStore) queryFromObject(raw json.RawMessage) (any, *LineError) {
793		q, err := parseQuery(raw)
794		if err != nil {
795			return nil, &LineError{Status: "error", Error: err.Error()}
796		}
797		if q.op == "query_windows" && !q.stepGiven {
798			return nil, &LineError{Status: "error", Error: `missing required field "step"`}
799		}
800		if q.start > q.end {
801			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
802				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
803		}
804		switch q.op {
805		case "query_points":
806			return s.runQueryPoints(q), nil
807		case "query_windows":
808			return s.runQueryWindows(q), nil
809		default:
810			return s.runQuery(q), nil
811		}
812	}
813	
814	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
815	// 以及仅 query_windows 使用的 step；拒绝重复键与未知字段；标量必须是精确的
816	// JSON 类型，start/end 为 int64 毫秒。op 只接受 "query"（区间点数与均值）、
817	// "query_points"（区间采样明细）与 "query_windows"（固定窗口均值），三种操作
818	// 共用同一套字段校验与区间规则。
819	//
820	// 错误选择沿用既有次序：结构完整的对象按字段书写顺序暴露问题，已出现字段全部
821	// 合法后才按 op、name、start、end 的顺序报告缺失的必填字段（step 是否必填要
822	// 等 op 确定，其缺失由 queryFromObject 在四项必填齐全后判定）。step 是否合法
823	// 由操作本身决定，与 op 的书写位置无关：先用 decidedQueryOp 预扫对象，op 恰好
824	// 出现一次且为受支持操作时即已确定——query 与 query_points 携带 step 一律是
825	// 未知字段，无论 step 写在 op 前后、值是正整数、零、字符串还是对象，都在 step
826	// 自己的书写位置按未知字段拒绝，绝不退化成窗口宽度校验；query_windows 的 step
827	// 在出现处即按 JSON 正整数校验：int64 范围、大于零，缺失、类型不符或值不合法
828	// 都指出 step。op 缺失、重复、类型不符或取值未知时无法据此判定 step，回退到
829	// 既有行为：step 在出现处按窗口宽度校验，op 自身的问题仍按书写次序暴露。
830	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
831		var q parsedQuery
832		q.basicGiven = map[string]bool{}
833		decidedOp := decidedQueryOp(raw)
834		err := parseStrictObject(raw,
835			"each query must be a JSON object",
836			"unexpected content after the query object",
837			nil,
838			map[string]fieldReader{
839				"op": func(dec *json.Decoder) error {
840					q.basicGiven["op"] = true
841					t, err := dec.Token()
842					if err != nil {
843						return err
844					}
845					op, ok := t.(string)
846					if !ok {
847						return fmt.Errorf(`field "op" must be a string`)
848					}
849					if op != "query" && op != "query_points" && op != "query_windows" {
850						return fmt.Errorf(`unknown op %q (only "query", "query_points" and "query_windows" are supported)`, op)
851					}
852					q.op = op
853					return nil
854				},
855				"name": func(dec *json.Decoder) error {
856					q.basicGiven["name"] = true
857					return readNameField(dec, &q.name)
858				},
859				"start": func(dec *json.Decoder) error {
860					q.basicGiven["start"] = true
861					return readInt64Field(dec, "start", &q.start)
862				},
863				"end": func(dec *json.Decoder) error {
864					q.basicGiven["end"] = true
865					return readInt64Field(dec, "end", &q.end)
866				},
867				"labels": func(dec *json.Decoder) error {
868					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
869				},
870				"step": func(dec *json.Decoder) error {
871					// 操作已确定且不是 query_windows：对该操作 step 是未知字段，
872					// 不读其值，直接按书写次序拒绝（与 parseStrictObject 的未知字段
873					// 处理一致）。确定的途径有两种：op 已写在 step 之前并成功读取
874					// （q.op），或预扫发现 op 恰好出现一次且为受支持操作
875					// （decidedOp，覆盖 step 写在 op 之前的情形）——两种途径下
876					// step 的值都无关紧要，正整数、零、字符串、对象同样拒绝。
877					if q.op != "" && q.op != "query_windows" {
878						return fmt.Errorf(`unknown field "step"`)
879					}
880					if decidedOp == "query" || decidedOp == "query_points" {
881						return fmt.Errorf(`unknown field "step"`)
882					}
883					if err := readInt64Field(dec, "step", &q.step); err != nil {
884						return err
885					}
886					if q.step <= 0 {
887						return fmt.Errorf(`field "step": must be greater than zero`)
888					}
889					q.stepGiven = true
890					return nil
891				},
892			})
893		if err != nil {
894			return q, err
895		}
896		// op 写在 step 之后时，读完对象才知道 step 对该 op 是否合法；该判定属于
897		// “已出现字段的合法性”，必须先于下面的必填字段缺失检查。op 本身缺失时不在这里
898		// 判定 step 未知——请求可能是漏写 op 的 query_windows，交给下面的固定必填次序
899		// 先报告 op（与“缺字段检查先于区间检查”等既有选择规则一致）。
900		if q.stepGiven && q.op != "" && q.op != "query_windows" {
901			return q, fmt.Errorf(`unknown field "step"`)
902		}
903		// 必填项固定按 op、name、start、end 的顺序报告第一个缺项，与字段书写位置无关。
904		for _, field := range []string{"op", "name", "start", "end"} {
905			if !q.basicGiven[field] {
906				return q, fmt.Errorf("missing required field %q", field)
907			}
908		}
909		return q, nil
910	}
911	
912	// decidedQueryOp 预扫查询对象的顶层字段，确定用于判定 step 是否合法的操作：
913	// op 恰好出现一次且取值是三个受支持操作之一时返回该操作；其余情况（op 缺失、
914	// 重复出现、不是字符串或取值未知）返回空串，表示无法据此判定，step 的校验
915	// 回退到按窗口宽度进行的既有行为。预扫只读不写：字段的逐项校验与错误暴露
916	// 仍由 parseStrictObject 按书写次序完成，op 自身的类型错误、未知取值与重复
917	// 出现都在 op 的书写位置按既有措辞报告。键名比较与 parseStrictObject 一样
918	// 在转义还原后进行，因此以转义形式书写的 op 同样被识别。
919	func decidedQueryOp(raw json.RawMessage) string {
920		dec := json.NewDecoder(bytes.NewReader(raw))
921		tok, err := dec.Token()
922		if err != nil {
923			return ""
924		}
925		if d, ok := tok.(json.Delim); !ok || d != '{' {
926			return ""
927		}
928		op := ""
929		opCount := 0
930		for dec.More() {
931			keyTok, err := dec.Token()
932			if err != nil {
933				return ""
934			}
935			key, _ := keyTok.(string)
936			var value json.RawMessage
937			if err := dec.Decode(&value); err != nil {
938				return ""
939			}
940			if key != "op" {
941				continue
942			}
943			opCount++
944			var s string
945			if err := json.Unmarshal(value, &s); err != nil {
946				return ""
947			}
948			op = s
949		}
950		if opCount != 1 {
951			return ""
952		}
953		switch op {
954		case "query", "query_points", "query_windows":
955			return op
956		}
957		return ""
958	}
959	
960	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
961	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
962	func labelsMatch(want, stored map[string]string) bool {
963		for k, v := range want {
964			got, ok := stored[k]
965			if !ok || got != v {
966				return false
967			}
968		}
969		return true
970	}
971	
972	// matchSeries 筛出名称精确匹配且标签子集命中的已存序列，供三种查询操作各自整理；
973	// 只读，不改变存储。
974	func (s *MetricStore) matchSeries(q parsedQuery) []*storedSeries {
975		matched := make([]*storedSeries, 0)
976		for _, sr := range s.series {
977			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
978				continue
979			}
980			matched = append(matched, sr)
981		}
982		return matched
983	}
984	
985	// pointStats 是区间统计（query）与固定窗口统计（query_windows）共用的
986	// 点数与均值累计器：逐点累计个数与精确有理数总和。写入侧已保证值有限，
987	// SetFloat64 对有限值是精确的，因此求和与点的提交顺序、批次划分无关，
988	// 正负大数抵消后的微小余量不会丢失，总和超出 float64 有限范围时均值仍有限。
989	// 两种统计只在“哪些点归入哪一组”上不同，点数与均值规则统一由这里维护。
990	type pointStats struct {
991		count int
992		sum   *big.Rat
993		tmp   *big.Rat
994	}
995	
996	func newPointStats() *pointStats {
997		return &pointStats{sum: new(big.Rat), tmp: new(big.Rat)}
998	}
999	
1000	// add 把一个实际保存的 float64 采样值计入统计。
1001	func (a *pointStats) add(v float64) {
1002		a.count++
1003		a.sum.Add(a.sum, a.tmp.SetFloat64(v))
1004	}
1005	
1006	// reset 清空累计，供下一个互不影响的统计范围（如后一个窗口）复用同一累计器：
1007	// 前一个范围的点数与数值一律不带入后一个范围。
1008	func (a *pointStats) reset() {
1009		a.count = 0
1010		a.sum = new(big.Rat)
1011	}
1012	
1013	// average 返回精确算术平均舍入到最近可表示 float64 的结果（正中取偶；
1014	// 精确为零时返回 +0）。调用方保证至少 add 过一次。不改动累计状态。
1015	func (a *pointStats) average() float64 {
1016		return ratToFloat64NearestEven(new(big.Rat).Quo(a.sum, a.tmp.SetInt64(int64(a.count))))
1017	}
1018	
1019	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
1020	// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
1021	// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
1022	// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
1023	// 结果一致。查询只返回每条序列的点数与均值，不构造采样明细列表（明细由
1024	// query_points 操作提供）——单次遍历点表直接累计进 pointStats（计数与
1025	// 均值都与点的排列次序无关）。区间内没有点的序列不列出，不补零值条目。
1026	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
1027		organized := organizeSeries(s.matchSeries(q))
1028	
1029		out := make([]QuerySeries, 0, len(organized))
1030		for _, entry := range organized {
1031			// 一次遍历直接统计：不构造值切片、不排序时间戳，避免为只返回
1032			// count/average 的查询承担采样明细展示。点数与均值的累计和舍入
1033			// 规则与固定窗口统计共用 pointStats。
1034			stats := newPointStats()
1035			for ts, v := range entry.sr.points {
1036				if ts < q.start || ts > q.end {
1037					continue
1038				}
1039				stats.add(v)
1040			}
1041			if stats.count == 0 {
1042				continue
1043			}
1044			out = append(out, QuerySeries{
1045				Name:    entry.ref.Name,
1046				Labels:  entry.ref.Labels,
1047				Count:   stats.count,
1048				Average: stats.average(),
1049			})
1050		}
1051		return &QueryResult{Status: "ok", Op: "query", Series: out}
1052	}
1053	
1054	// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
1055	// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
1056	// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
1057	// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
1058	// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
1059	// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
1060	// float64。查询只读，不改变采样值或写入计数。
1061	func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
1062		organized := organizeSeries(s.matchSeries(q))
1063	
1064		out := make([]QueryPointsSeries, 0, len(organized))
1065		for _, entry := range organized {
1066			points := seriesPointsInRange(entry.sr, q.start, q.end)
1067			if len(points) == 0 {
1068				continue
1069			}
1070			out = append(out, QueryPointsSeries{
1071				Name:   entry.ref.Name,
1072				Labels: entry.ref.Labels,
1073				Points: points,
1074			})
1075		}
1076		return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
1077	}
1078	
1079	// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
1080	// 内的采样点，供采样明细查询展示。选取、升序排列与点构造与写入快照共用
1081	// seriesPoints，区别只在传入的选取范围是闭区间而不是全部。
1082	func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
1083		return seriesPoints(sr, func(ts int64) bool { return ts >= start && ts <= end })
1084	}
1085	
1086	// runQueryWindows 只读统计固定时间窗口内的点数与均值：窗口把 [start,end]
1087	// 闭区间按 step 毫秒从 start 起连续划分，第 k 个窗口为
1088	// [start+k*step, start+(k+1)*step-1]（含首尾毫秒），最后一个截到 end，
1089	// 各序列共用同一组由 start 与 step 决定的边界——因此不为空窗口构造任何条目，
1090	// 即使区间横跨整个 int64 也不预先物化窗口表。
1091	//
1092	// 名称精确、标签子集的序列筛选与 organizeSeries 整理、序列排列次序和另两种
1093	// 查询完全一致。每条序列独立统计：先取区间内按时间戳升序的采样点，升序点流
1094	// 中落在同一窗口的点必然连续，据此一次遍历分窗，逐窗口用 pointStats 累计
1095	// 点数与均值——与区间统计共用同一套计数、精确求和与舍入规则；窗口切换时
1096	// reset，前一窗口的点数与数值不带入后一窗口。只输出实际有点的窗口，按窗口
1097	// 起点升序，空窗口不补零，整个区间没有点的序列不列出，无任何命中时 series
1098	// 为空数组。每个点只归入 floor((ts-start)/step) 唯一窗口；start==end 时所有
1099	// 点归入唯一窗口。平均值依据实际存储的 float64 值计算，正负大数抵消或总和
1100	// 超出 float64 范围时仍得有限结果。查询只读，不改变存储。
1101	func (s *MetricStore) runQueryWindows(q parsedQuery) *QueryWindowsResult {
1102		organized := organizeSeries(s.matchSeries(q))
1103	
1104		// diff = end - start，可能达到 2^64-1（start 为 MinInt64、end 为 MaxInt64），
1105		// 只能以 uint64 承载；窗口下标与窗口内偏移都在这个无符号区间内运算。
1106		diff := uint64(q.end) - uint64(q.start)
1107	
1108		out := make([]QueryWindowsSeries, 0, len(organized))
1109		for _, entry := range organized {
1110			points := seriesPointsInRange(entry.sr, q.start, q.end)
1111			if len(points) == 0 {
1112				continue
1113			}
1114			windows := make([]Window, 0)
1115			var curIdx uint64
1116			stats := newPointStats()
1117			flush := func() {
1118				windows = append(windows, buildWindow(q.start, q.end, q.step, diff, curIdx, stats))
1119			}
1120			for i, p := range points {
1121				// 无符号偏移除以 step 得窗口下标；升序点流下标单调不减。
1122				idx := (uint64(p.Timestamp) - uint64(q.start)) / uint64(q.step)
1123				if i > 0 && idx != curIdx {
1124					flush()
1125					stats.reset()
1126				}
1127				curIdx = idx
1128				stats.add(p.Value)
1129			}
1130			flush()
1131			out = append(out, QueryWindowsSeries{
1132				Name:    entry.ref.Name,
1133				Labels:  entry.ref.Labels,
1134				Windows: windows,
1135			})
1136		}
1137		return &QueryWindowsResult{Status: "ok", Op: "query_windows", Series: out}
1138	}
1139	
1140	// buildWindow 构造一个非空窗口的统计：窗口起点是 start + idx*step，终点是
1141	// 起点加 step 减一；起点加 step 减一越过查询区间（含无符号加法溢出）时截到
1142	// end。点数与均值取自该窗口独立累计的 stats，均值按与 query 相同的精确平均
1143	// 与居中取偶规则得出（精确为零返回 +0）。调用方保证 0 <= idx*step <= diff，
1144	// 且 stats 至少计入了一个点。
1145	func buildWindow(start, end, step int64, diff, idx uint64, stats *pointStats) Window {
1146		startOff := idx * uint64(step)
1147		wStart := int64AtOffset(start, startOff)
1148		wEnd := end
1149		// tail <= diff-startOff 的比较不做 startOff+tail 加法，避免无符号溢出
1150		// （step 接近 2^63 时朴素相加可能绕过 2^64）。
1151		if tail := uint64(step) - 1; tail <= diff-startOff {
1152			wEnd = int64AtOffset(start, startOff+tail)
1153		}
1154		return Window{
1155			Start:   wStart,
1156			End:     wEnd,
1157			Count:   stats.count,
1158			Average: stats.average(),
1159		}
1160	}
1161	
1162	// int64AtOffset 返回 start + off（0 <= off，且调用方保证结果不超过 MaxInt64）。
1163	// 直接做有符号相加在 start 接近 int64 下界、off 很大时会溢出，因此统一走
1164	// 无符号运算还原：start 非负时无符号相加必落在非负有符号范围；start 为负时
1165	// 以 -start 为界先回到非正区间、再跨入正区间，两个分支都不产生溢出。
1166	func int64AtOffset(start int64, off uint64) int64 {
1167		if start >= 0 {
1168			return int64(uint64(start) + off)
1169		}
1170		gap := uint64(-start) // 0 < gap <= 2^63（start 为 MinInt64 时恰为 2^63）
1171		if off <= gap {
1172			// gap-off 为 2^63 时 int64 表示恰为 MinInt64，取负仍是 MinInt64，语义正确。
1173			return -int64(gap - off)
1174		}
1175		return int64(off - gap)
1176	}
1177	
1178	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
1179	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
1180	func ratToFloat64NearestEven(x *big.Rat) float64 {
1181		if x.Sign() == 0 {
1182			return 0
1183		}
1184		num := new(big.Int).Set(x.Num())
1185		den := x.Denom()
1186		neg := num.Sign() < 0
1187		if neg {
1188			num.Neg(num)
1189		}
1190	
1191		// e 满足 2^e <= num/den < 2^(e+1)。
1192		e := floorLog2Rat(num, den)
1193		var m *big.Int
1194		scale := 0
1195		if e >= -1022 {
1196			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
1197			scale = e - 52
1198			m = roundScaledRatio(num, den, scale)
1199			if m.BitLen() == 54 {
1200				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
1201				m.Rsh(m, 1)
1202				scale++
1203			}
1204		} else {
1205			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
1206			scale = -1074
1207			m = roundScaledRatio(num, den, scale)
1208		}
1209		// m < 2^53，可以精确放入 int64 与 float64。
1210		f := math.Ldexp(float64(m.Int64()), scale)
1211		if neg {
1212			return -f
1213		}
1214		return f
1215	}
1216	
1217	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
1218	func floorLog2Rat(num, den *big.Int) int {
1219		k := num.BitLen() - den.BitLen()
1220		var t big.Int
1221		if k >= 0 {
1222			t.Lsh(den, uint(k))
1223			if num.Cmp(&t) >= 0 {
1224				return k
1225			}
1226			return k - 1
1227		}
1228		t.Lsh(num, uint(-k))
1229		if t.Cmp(den) >= 0 {
1230			return k
1231		}
1232		return k - 1
1233	}
1234	
1235	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
1236	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
1237		n := new(big.Int).Set(num)
1238		d := new(big.Int).Set(den)
1239		if scale >= 0 {
1240			d.Lsh(d, uint(scale))
1241		} else {
1242			n.Lsh(n, uint(-scale))
1243		}
1244		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
1245		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
1246		case 1:
1247			q.Add(q, big.NewInt(1))
1248		case 0:
1249			if q.Bit(0) == 1 {
1250				q.Add(q, big.NewInt(1))
1251			}
1252		}
1253		return q
1254	}
1255	
1256	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
1257	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
1258	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
1259	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
1260	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
1261	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
1262	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
1263	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
1264	func (r SeriesRef) String() string {
1265		var b strings.Builder
1266		b.WriteString(identityText(r.Name))
1267		b.WriteByte('{')
1268		for i, p := range sortedPairs(r.Labels) {
1269			if i > 0 {
1270				b.WriteByte(',')
1271			}
1272			b.WriteString(identityText(p.Key))
1273			b.WriteByte('=')
1274			b.WriteString(identityText(p.Value))
1275		}
1276		b.WriteByte('}')
1277		return b.String()
1278	}
1279	
1280	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
1281	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
1282	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
1283	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
1284	// 因此渲染结果不会把内容字符误读为标签边界。
1285	func identityText(s string) string {
1286		if s == "" || s != strings.TrimSpace(s) {
1287			return strconv.Quote(s)
1288		}
1289		for _, r := range s {
1290			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
1291				return strconv.Quote(s)
1292			}
1293		}
1294		return s
1295	}
1296	
1297	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
1298	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
1299	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
1300	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
1301	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
1302	type organizedSeries struct {
1303		sr    *storedSeries
1304		ref   SeriesRef
1305		pairs []labelPair
1306	}
1307	
1308	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
1309	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
1310	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
1311	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
1312	// 与冲突原因里的展示文字、标签的输入次序无关。
1313	func seriesLess(a, b organizedSeries) bool {
1314		if a.ref.Name != b.ref.Name {
1315			return a.ref.Name < b.ref.Name
1316		}
1317		return compareLabelPairs(a.pairs, b.pairs) < 0
1318	}
1319	
1320	// organizeSeries 是写入快照与三种查询成功结果共用的序列身份整理：对入选的每条已存序列
1321	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
1322	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，三种区间查询只
1323	// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
1324	// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
1325	// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
1326	// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
1327	// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
1328	// seriesPointsInRange 按区间选取并升序排列，固定窗口查询在区间升序点流上
1329	// 按窗口累计计数与精确求和。
1330	func organizeSeries(selected []*storedSeries) []organizedSeries {
1331		out := make([]organizedSeries, 0, len(selected))
1332		for _, sr := range selected {
1333			// 标签必须复制：成功结果是当次操作的独立记录，
1334			// 调用方修改结果标签不能改动已存序列的身份。
1335			labels := cloneLabels(sr.ref.Labels)
1336			out = append(out, organizedSeries{
1337				sr:    sr,
1338				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
1339				pairs: sortedPairs(labels),
1340			})
1341		}
1342		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
1343		return out
1344	}
1345	
1346	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，供写入快照
1347	// 展示。选取、升序排列与点构造与采样明细查询共用 seriesPoints，区别只在传入
1348	// 的选取范围是全部而不是闭区间。
1349	func allSeriesPoints(sr *storedSeries) []Point {
1350		return seriesPoints(sr, nil)
1351	}
1352	
1353	// seriesPoints 是写入快照与采样明细查询共用的采样点整理：从已存序列的点表中
1354	// 选出 keep 命中的时间戳（keep 为 nil 表示全部选取），按 timestamp 升序排列，
1355	// 每个时间戳配上点表中实际存储的 value（数值与时间戳一一对应，排序只动时间戳
1356	// 列表、不重配对值；int64 比较保留整数精度，float64 原样取出，负零保持负零）。
1357	// 返回的是新建切片与新建 Point，不持有点表的任何引用：调用方对结果的修改不
1358	// 影响存储，也不影响此前或此后取得的其他成功结果；取得结果后再写入新点，该份
1359	// 结果也不跟随存储变化。均值查询不构造这样的明细列表，只在点表上计数与求和。
1360	func seriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
1361		tsList := make([]int64, 0, len(sr.points))
1362		for ts := range sr.points {
1363			if keep != nil && !keep(ts) {
1364				continue
1365			}
1366			tsList = append(tsList, ts)
1367		}
1368		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
1369		points := make([]Point, len(tsList))
1370		for i, ts := range tsList {
1371			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
1372		}
1373		return points
1374	}
1375	
1376	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
1377	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
1378	// 三种区间查询共用同一套身份整理，各自只对命中序列统计均值、列出明细或
1379	// 按固定窗口统计。
1380	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
1381		all := make([]*storedSeries, 0, len(s.series))
1382		for _, sr := range s.series {
1383			all = append(all, sr)
1384		}
1385		organized := organizeSeries(all)
1386		views := make([]SeriesView, 0, len(organized))
1387		for _, os := range organized {
1388			views = append(views, SeriesView{
1389				Name:   os.ref.Name,
1390				Labels: os.ref.Labels,
1391				Points: allSeriesPoints(os.sr),
1392			})
1393		}
1394		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
1395	}
1396

