134				t.Fatalf("mutated timestamps %s must not be stored, got %+v", line, qr.Series)
135			}
136		}
137	
138		// 先前保留的另一份明细结果保留各自原有的标签、点与次序。
139		wantKept := []struct {
140			labels map[string]string
141			points []Point
142		}{
143			{map[string]string{}, []Point{{Timestamp: 1000, Value: 6}}},
144			{map[string]string{"host": "a"}, hostA},
145			{map[string]string{"host": "b"}, hostB},
146			{map[string]string{"zone": ""}, []Point{{Timestamp: 1000, Value: 7}}},
147		}
148		if kept.Status != "ok" || kept.Op != "query_points" || len(kept.Series) != len(wantKept) {
149			t.Fatalf("retained query_points envelope/series changed: %+v", kept)
150		}
151		for i, w := range wantKept {
152			got := kept.Series[i]
153			if got.Name != "cpu" || !reflect.DeepEqual(got.Labels, w.labels) ||
154				!reflect.DeepEqual(got.Points, w.points) {
155				t.Fatalf("retained query_points series[%d] = %+v, want labels %v points %+v",
156					i, got, w.labels, w.points)
157			}
158		}
159	
160		// 写入快照也保留原有标签、点与次序。
161		snap := mustOK(t, s, `[]`)
162		if len(snap.Series) != 4 {
163			t.Fatalf("snapshot after query_points mutation = %+v, want 4 series", snap.Series)
164		}
165		snapA := snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "a"})]
166		if !reflect.DeepEqual(snapA.Points, hostA) {
167			t.Fatalf("snapshot host=a points = %+v, want %+v", snapA.Points, hostA)
168		}
169		snapB := snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "b"})]
170		if !reflect.DeepEqual(snapB.Points, hostB) {
171			t.Fatalf("snapshot host=b points = %+v, want %+v", snapB.Points, hostB)
172		}
173	
174		// 原序列、原时间戳、原值再次提交仍计为重复（存储认的是真实值，不是改出的 90/55）。
175		dup := mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
176		if dup.Added != 0 || dup.Duplicates != 1 {
177			t.Fatalf("resubmit original host=a point = %+v, want one duplicate", dup)
178		}
179		dup = mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}]`)
180		if dup.Added != 0 || dup.Duplicates != 1 {
181			t.Fatalf("resubmit original host=b point = %+v, want one duplicate", dup)
182		}
183	
184		// 对同一位置提交不同值仍拒绝整批；冲突中的已存在值来自真实存储，
185		// 不受返回结果里改出的数值影响（host=a 改出的 90、host=b 改出的 55）。
186		lerr := mustFail(t, s, `[
187			{"name":"cpu","timestamp":3000,"value":99,"labels":{"host":"a"}},
188			{"name":"cpu","timestamp":1000,"value":123,"labels":{"host":"a"}}
189		]`)
190		if lerr.Index != 1 || lerr.Conflict == nil {
191			t.Fatalf("conflict must target the first conflicting point, got %+v", lerr)
192		}
193		c := lerr.Conflict
194		if c.Series.Name != "cpu" || len(c.Series.Labels) != 1 || c.Series.Labels["host"] != "a" ||
195			c.Timestamp != 3000 || c.Existing != 6 || c.Submitted != 99 {
196			t.Fatalf("host=a conflict must report stored fact, got %+v", c)
197		}
198		lerr = mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":55,"labels":{"host":"b"}}]`)
199		if lerr.Conflict == nil || lerr.Conflict.Existing != 5 || lerr.Conflict.Submitted != 55 {
200			t.Fatalf("host=b conflict must report existing=5, got %+v", lerr.Conflict)
201		}
202		// 整批拒绝：本批没有任何点留下。
203		if dup = mustOK(t, s, `[{"name":"cpu","timestamp":3000,"value":6,"labels":{"host":"a"}}]`); dup.Duplicates != 1 {
204			t.Fatalf("conflict batch must not write anything, got %+v", dup)
205		}
206	
207		// 均值查询的点数与平均值仍是原始数据对应的结果，展示时追加/改出的点不算。
208		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
209		if len(qr.Series) != 1 || qr.Series[0].Count != 3 || qr.Series[0].Average != 4 {
210			t.Fatalf("host=a average after mutation = %+v, want count=3 average=4", qr.Series)
211		}
212	}
213	
214	// TestQueryPointsEmptyAndEmptyValueLabelsIndependent 保留两种容易混淆的标签
215	// 情况：无标签序列与某个标签确实存在但值为空字符串的序列。给返回的空标签集合
216	// 加键、删除返回的空值标签，都不能合并或改写这两条真实序列；原标签筛选仍成立。
217	func TestQueryPointsEmptyAndEmptyValueLabelsIndependent(t *testing.T) {
218		s := NewMetricStore()
219		mustOK(t, s, `[
220			{"name":"cpu","timestamp":1000,"value":6},
221			{"name":"cpu","timestamp":2000,"value":8},
222			{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}},
223			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}
224		]`)
225	
226		res := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000}`)
227		none := &res.Series[findPointsIndex(t, res, "cpu", map[string]string{})]
228		if none.Labels == nil {
229			t.Fatal("query_points labels for unlabeled series must be non-nil empty map")
230		}
231		emptyVal := &res.Series[findPointsIndex(t, res, "cpu", map[string]string{"zone": ""})]
232	
233		// 调用方整理两个返回视图：空集合加键、空值标签删键、改点值与时间戳。
234		none.Labels["host"] = "x"
235		none.Points[0].Value = 66
236		delete(emptyVal.Labels, "zone")
237		emptyVal.Points[0].Timestamp = 5000
238		emptyVal.Points[0].Value = 77
239	
240		// 三条真实序列不被合并或改写：全量明细仍是三条序列。
241		again := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000}`)
242		if len(again.Series) != 3 {
243			t.Fatalf("full query_points = %+v, want 3 distinct series", again.Series)
244		}
245		gotNone := again.Series[findPointsIndex(t, again, "cpu", map[string]string{})]
246		if !reflect.DeepEqual(gotNone.Points, []Point{{Timestamp: 1000, Value: 6}, {Timestamp: 2000, Value: 8}}) {
247			t.Fatalf("unlabeled series points changed: %+v", gotNone.Points)
248		}
249		gotEmpty := again.Series[findPointsIndex(t, again, "cpu", map[string]string{"zone": ""})]
250		if !reflect.DeepEqual(gotEmpty.Points, []Point{{Timestamp: 1000, Value: 7}}) {
251			t.Fatalf("empty-value series points changed: %+v", gotEmpty.Points)
252		}
253	
254		// 原标签筛选仍成立：加出来的 host=x 不命中；空值标签筛选仍只命中真实空值序列。
255		if qr := mustQueryPoints(t, s,
256			`{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"x"}}`); len(qr.Series) != 0 {
257			t.Fatalf("added label must not match: %+v", qr.Series)
258		}
259		zoneEmpty := mustQueryPoints(t, s,
260			`{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"zone":""}}`)
261		if len(zoneEmpty.Series) != 1 ||
262			!reflect.DeepEqual(zoneEmpty.Series[0].Labels, map[string]string{"zone": ""}) ||
263			!reflect.DeepEqual(zoneEmpty.Series[0].Points, []Point{{Timestamp: 1000, Value: 7}}) {
264			t.Fatalf("empty-value label selection = %+v, want the zone='' series", zoneEmpty.Series)
265		}
266		// 删除返回的空值标签后，空条件（{}）仍按全部序列返回，两条身份各自保留：
267		// 无标签条目仍是空集合，zone="" 条目仍带该键，不会被合并成一条。
268		allSeries := mustQueryPoints(t, s,
269			`{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{}}`)
270		if len(allSeries.Series) != 3 {
271			t.Fatalf("empty-label selection = %+v, want all 3 series with distinct identities", allSeries.Series)
272		}
273		if got := allSeries.Series[findPointsIndex(t, allSeries, "cpu", map[string]string{})].Labels; len(got) != 0 {
274			t.Fatalf("unlabeled identity must stay label-free, got %v", got)
275		}
276		zoneEntry := allSeries.Series[findPointsIndex(t, allSeries, "cpu", map[string]string{"zone": ""})]
277		if v, ok := zoneEntry.Labels["zone"]; !ok || v != "" || len(zoneEntry.Labels) != 1 {
278			t.Fatalf("zone='' identity must keep its single key, got %v", zoneEntry.Labels)
279		}
280		// 改出的时间戳 5000 不存在。
281		if qr := mustQueryPoints(t, s,
282			`{"op":"query_points","name":"cpu","start":4000,"end":6000,"labels":{"zone":""}}`); len(qr.Series) != 0 {
283			t.Fatalf("mutated timestamp must not be stored: %+v", qr.Series)
284		}
285	
286		// 均值查询同样不合并两条序列。
287		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
288		if len(qr.Series) != 3 {
289			t.Fatalf("full average query = %+v, want 3 distinct series", qr.Series)
290		}
291		if q := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{})]; q.Count != 2 || q.Average != 7 {
292			t.Fatalf("unlabeled average = %+v, want count=2 average=7", q)
293		}
294		if q := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{"zone": ""})]; q.Count != 1 || q.Average != 7 {
295			t.Fatalf("empty-value average = %+v, want count=1 average=7", q)
296		}
297	
298		// 后续写入仍按真实身份判定重复与冲突。
299		if dup := mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":6}]`); dup.Added != 0 || dup.Duplicates != 1 {
300			t.Fatalf("unlabeled resubmit must duplicate, got %+v", dup)
301		}
302		lerr := mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":77,"labels":{"zone":""}}]`)
303		if lerr.Conflict == nil || lerr.Conflict.Existing != 7 || lerr.Conflict.Submitted != 77 {
304			t.Fatalf("empty-value conflict must report existing=7, got %+v", lerr.Conflict)
305		}
306	}
307	
308	// TestRetainedQueryPointsStayFixedAfterNewWrite 保留一份未修改的明细结果后再
309	// 成功写入新时间戳：新查询应看到新增点，旧结果仍表示取得时的内容（标签、点、
310	// 次序都不跟随新写入变化）；同一存储上更早保留的写入快照同样固定。
311	func TestRetainedQueryPointsStayFixedAfterNewWrite(t *testing.T) {
312		s := NewMetricStore()
313		snapBefore := mustOK(t, s, `[
314			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
315			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
316			{"name":"cpu","timestamp":1000,"value":8,"labels":{"host":"b"}}
317		]`)
318		qpBefore := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000}`)
319		hostABefore := []Point{{Timestamp: 1000, Value: 2}, {Timestamp: 2000, Value: 4}}
320		if len(qpBefore.Series) != 2 {
321			t.Fatalf("retained query_points baseline = %+v, want 2 series", qpBefore.Series)
322		}
323		if got := qpBefore.Series[findPointsIndex(t, qpBefore, "cpu", map[string]string{"host": "a"})]; !reflect.DeepEqual(got.Points, hostABefore) {
324			t.Fatalf("retained host=a points baseline = %+v, want %+v", got.Points, hostABefore)
325		}
326	
327		// 成功写入新时间戳 3000->6。
328		write := mustOK(t, s, `[{"name":"cpu","timestamp":3000,"value":6,"labels":{"host":"a"}}]`)
329		if write.Added != 1 || write.Duplicates != 0 {
330			t.Fatalf("new timestamp write = %+v, want added=1", write)
331		}
332	
333		// 新查询看到新增点，按时间戳升序排在最后。
334		qpAfter := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
335		wantAfter := append(hostABefore, Point{Timestamp: 3000, Value: 6})
336		if len(qpAfter.Series) != 1 || !reflect.DeepEqual(qpAfter.Series[0].Points, wantAfter) {
337			t.Fatalf("new query_points after write = %+v, want %+v", qpAfter.Series, wantAfter)
338		}
339	
340		// 先前保留的明细结果仍表示取得时的内容：host=a 只有两个点，host=b 不变。
341		if len(qpBefore.Series) != 2 {
342			t.Fatalf("retained query_points gained a series entry: %+v", qpBefore.Series)
343		}
344		gotA := qpBefore.Series[findPointsIndex(t, qpBefore, "cpu", map[string]string{"host": "a"})]
345		if !reflect.DeepEqual(gotA.Points, hostABefore) {
346			t.Fatalf("retained query_points host=a changed after new write: %+v", gotA.Points)
347		}
348		gotB := qpBefore.Series[findPointsIndex(t, qpBefore, "cpu", map[string]string{"host": "b"})]
349		if !reflect.DeepEqual(gotB.Points, []Point{{Timestamp: 1000, Value: 8}}) {
350			t.Fatalf("retained query_points host=b changed: %+v", gotB.Points)
351		}
352		if qpBefore.Status != "ok" || qpBefore.Op != "query_points" {
353			t.Fatalf("retained envelope changed: %+v", qpBefore)
354		}
355	
356		// 先前保留的写入快照同样不跟随变化。
357		if len(snapBefore.Series) != 2 {
358			t.Fatalf("retained snapshot gained a series: %+v", snapBefore.Series)
359		}
360		snapA := snapBefore.Series[findViewIndex(t, snapBefore, "cpu", map[string]string{"host": "a"})]
361		if !reflect.DeepEqual(snapA.Points, hostABefore) {
362			t.Fatalf("retained snapshot host=a changed after new write: %+v", snapA.Points)
363		}
364	
365		// 新写入的点也不应影响更早取得的点被篡改后的隔离：再取一份明细并篡改，
366		// 新写入的 3000 点在存储中仍是 6。
367		mut := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
368		mut.Series[0].Points[2].Value = 600
369		mut.Series[0].Points[2].Timestamp = 3001
370		fresh := mustQueryPoints(t, s, `{"op":"query_points","name":"cpu","start":3000,"end":3000,"labels":{"host":"a"}}`)
371		if !reflect.DeepEqual(fresh.Series[0].Points, []Point{{Timestamp: 3000, Value: 6}}) {
372			t.Fatalf("new point fact changed by mutating a later result: %+v", fresh.Series)
373		}
374	}
375	
376	// TestQueryPointsResultIndependentViaProcessLine 统一行处理入口 ProcessLine
377	// 返回的明细结果同样遵守隔离规则：通过类型断言取得 *QueryPointsResult 后修改其
378	// 指标名、标签、点与列表结构，不影响存储、另一份结果与后续经统一入口的写入判定。
379	func TestQueryPointsResultIndependentViaProcessLine(t *testing.T) {
380		s := NewMetricStore()
381		processOK(t, s, `[
382			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
383			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
384			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}
385		]`)
386	
387		// 通过统一入口取得第一份明细并保留（未修改）。
388		r := processOK(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000}`)
389		kept, ok := r.(*QueryPointsResult)
390		if !ok {
391			t.Fatalf("ProcessLine result type = %T, want *QueryPointsResult", r)
392		}
393		if len(kept.Series) != 2 {
394			t.Fatalf("baseline via ProcessLine = %+v, want 2 series", kept.Series)
395		}
396	
397		// 通过统一入口取得第二份明细并由调用方大幅整理。
398		r = processOK(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000}`)
399		res := r.(*QueryPointsResult)
400		a := &res.Series[findPointsIndex(t, res, "cpu", map[string]string{"host": "a"})]
401		a.Name = "renamed"
402		a.Labels["host"] = "c"
403		a.Points[0].Timestamp = 90001
404		a.Points[0].Value = 200
405		a.Points = a.Points[:1]
406		a.Points = append(a.Points, Point{Timestamp: 2, Value: 20})
407		b := &res.Series[findPointsIndex(t, res, "cpu", map[string]string{"host": "b"})]
408		delete(b.Labels, "host")
409		res.Series = res.Series[:1]
410		res.Status = "mutated"
411		res.Op = "mutated"
412	
413		// 存储事实不变：再经统一入口查询，host=a 仍是原始两个点。
414		r = processOK(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
415		fresh := r.(*QueryPointsResult)
416		if !reflect.DeepEqual(fresh.Series[0].Points,
417			[]Point{{Timestamp: 1000, Value: 2}, {Timestamp: 2000, Value: 4}}) {
418			t.Fatalf("host=a fact via ProcessLine changed: %+v", fresh.Series)
419		}
420		// host=b 同伴不受 host=a 视图修改影响。
421		r = processOK(t, s, `{"op":"query_points","name":"cpu","start":0,"end":10000,"labels":{"host":"b"}}`)
422		if !reflect.DeepEqual(r.(*QueryPointsResult).Series[0].Points, []Point{{Timestamp: 1000, Value: 5}}) {
423			t.Fatalf("host=b fact via ProcessLine changed: %+v", r)
424		}
425		// 改出的身份与时间戳查不到数据。
426		for _, line := range []string{
427			`{"op":"query_points","name":"cpu","start":0,"end":100000,"labels":{"host":"c"}}`,
428			`{"op":"query_points","name":"renamed","start":0,"end":100000}`,
429			`{"op":"query_points","name":"cpu","start":90000,"end":91000,"labels":{"host":"a"}}`,
430		} {
431			r = processOK(t, s, line)
432			if len(r.(*QueryPointsResult).Series) != 0 {
433				t.Fatalf("mutated identity/timestamp %s must not match: %+v", line, r)
434			}
435		}
436	
437		// 先前保留的明细结果不被污染。
438		if kept.Status != "ok" || kept.Op != "query_points" || len(kept.Series) != 2 {
439			t.Fatalf("retained ProcessLine result changed: %+v", kept)
440		}
441		keptA := kept.Series[findPointsIndex(t, kept, "cpu", map[string]string{"host": "a"})]
442		if !reflect.DeepEqual(keptA.Points, []Point{{Timestamp: 1000, Value: 2}, {Timestamp: 2000, Value: 4}}) {
443			t.Fatalf("retained ProcessLine host=a points changed: %+v", keptA.Points)
444		}
445	
446		// 后续写入经统一入口仍按真实存储判定：原值重复、不同值冲突且 existing 为真实值。
447		r = processOK(t, s, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
448		br := r.(*BatchResult)
449		if br.Added != 0 || br.Duplicates != 1 {
450			t.Fatalf("duplicate via ProcessLine = %+v, want one duplicate", br)
451		}
452		lerr := processFail(t, s, `[{"name":"cpu","timestamp":1000,"value":200,"labels":{"host":"a"}}]`)
453		if lerr.Conflict == nil || lerr.Conflict.Existing != 2 || lerr.Conflict.Submitted != 200 {
454			t.Fatalf("conflict via ProcessLine must report existing=2, got %+v", lerr.Conflict)
455		}
456	
457		// 均值查询经统一入口仍是原始数据的点数与平均值。
458		r = processOK(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
459		qa := r.(*QueryResult)
460		if len(qa.Series) != 1 || qa.Series[0].Count != 2 || qa.Series[0].Average != 3 {
461			t.Fatalf("average via ProcessLine = %+v, want count=2 average=3", qa.Series)
462		}
463	}
