365			t.Fatalf("new query after write = %+v, want count=3 average=4", qAfter.Series)
366		}
367		snapAfter := mustOK(t, s, `[]`)
368		aAfter := snapAfter.Series[findViewIndex(t, snapAfter, "cpu", map[string]string{"host": "a"})]
369		if len(aAfter.Points) != 3 || aAfter.Points[2] != (Point{Timestamp: 3000, Value: 6}) {
370			t.Fatalf("new snapshot must include new point, got %+v", aAfter.Points)
371		}
372	
373		// 先前保留的写入快照不跟着变化。
374		aBefore := snapBefore.Series[findViewIndex(t, snapBefore, "cpu", map[string]string{"host": "a"})]
375		if len(snapBefore.Series) != 2 || len(aBefore.Points) != 2 ||
376			aBefore.Points[0] != (Point{Timestamp: 1000, Value: 2}) ||
377			aBefore.Points[1] != (Point{Timestamp: 2000, Value: 4}) {
