124	// processHostAQuery 通过统一入口查询覆盖 [start,end] 的 cpu{host=a}，
125	// 返回查询结果（无命中时 Series 为空，由调用方自行判定）。
126	func processHostAQuery(t *testing.T, store *MetricStore, start, end int64) *QueryResult {
127		t.Helper()
128		line := `{"op":"query","name":"cpu","start":` + strconv.FormatInt(start, 10) +
129			`,"end":` + strconv.FormatInt(end, 10) + `,"labels":{"host":"a"}}`
130		r := processOK(t, store, line)
131		qr, ok := r.(*QueryResult)
132		if !ok {
133			t.Fatalf("query result type = %T, want *QueryResult", r)
134		}
