261	// README 中的冲突场景经统一入口复现：先合法写入 1000->2，再提交 2000->4 的
262	// 新增点和 1000->9 的冲突点，整批拒绝；错误指向批内第 2 个点并保留完整冲突
263	// 细节，随后覆盖两个时间戳的查询仍只有 1 个点、均值 2。
264	func TestProcessLineConflictRejectsWholeBatch(t *testing.T) {
