294	
295	// 采样点字段校验失败时，同一批前面已经解析通过的新增点同样不提交；
296	// 错误继续携带批内出错位置，但不附带数值冲突详情。
297	func TestProcessLineFieldValidationRollsBackEarlierSamples(t *testing.T) {
298		store := NewMetricStore()
299		processSeedHostA(t, store)
300	
301		lerr := processFail(t, store, `[
302			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
303			{"name":"cpu","timestamp":"soon","value":3,"labels":{"host":"a"}}
304		]`)
305		if lerr.Index != 2 {
306			t.Fatalf("index = %d, want 2", lerr.Index)
307		}
308		if !strings.Contains(lerr.Error, `field "timestamp" must be a JSON number`) {
309			t.Fatalf("error = %q, want timestamp type reason", lerr.Error)
310		}
311		if lerr.Conflict != nil {
312			t.Fatalf("field validation failure must not carry conflict detail, got %+v", lerr.Conflict)
313		}
314	
315		// 第 1 个点是合法新增，也必须随整批回滚。
316		qr := processHostAQuery(t, store, 0, 3000)
317		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
318			t.Fatalf("earlier valid sample must be rolled back too, got %+v", qr.Series)
319		}
320	}
321	
322	// 可解析但字段类型不合法或区间倒置的查询对象返回对应原因的结构化错误，
323	// 不带写入批内位置或冲突详情；失败查询不改变存储，随后合法查询照常命中。
324	func TestProcessLineQueryFailuresAreReasonOnlyAndReadOnly(t *testing.T) {
325		store := NewMetricStore()
326		processSeedHostA(t, store)
327	
328		baseline := func() {
329			t.Helper()
330			qr := processHostAQuery(t, store, 0, 3000)
331			if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
332				t.Fatalf("baseline data changed by failed query: %+v", qr.Series)
333			}
334		}
335		baseline()
336	
337		for _, tc := range []struct {
338			name string
339			line string
340			want string
341		}{
342			{"name wrong type", `{"op":"query","name":7,"start":0,"end":3000}`, `field "name" must be a string`},
343			{"start wrong type",
344				`{"op":"query","name":"cpu","start":"0","end":3000,"labels":{"host":"a"}}`,
345				`field "start" must be a JSON number`},
346			{"labels wrong type", `{"op":"query","name":"cpu","start":0,"end":3000,"labels":[]}`,
347				`field "labels" must be an object`},
348			{"missing end", `{"op":"query","name":"cpu","start":0}`, `missing required field "end"`},
349			{"unknown op", `{"op":"ping","name":"cpu","start":0,"end":3000}`, `unknown op "ping"`},
350			{"inverted range",
351				`{"op":"query","name":"cpu","start":5000,"end":1000,"labels":{"host":"a"}}`,
352				"5000 > 1000"},
353		} {
354			t.Run(tc.name, func(t *testing.T) {
355				lerr := processFail(t, store, tc.line)
356				if !strings.Contains(lerr.Error, tc.want) {
357					t.Fatalf("error = %q, want substring %q", lerr.Error, tc.want)
358				}
359				if lerr.Index != 0 || lerr.Conflict != nil {
360					t.Fatalf("query failure must not carry index/conflict, got %+v", lerr)
361				}
362				m := marshalLineError(t, lerr)
363				assertNoBatchPositionOrConflict(t, m, tc.line)
364			})
365		}
366	
367		// 所有失败查询之后，合法查询结果与失败前一致。
368		baseline()
369	}
370	
371	// 空写入批次与无命中查询是“没有新增/没有命中”，不是失败：结果必须非 nil、
372	// 错误必须为 nil；空数组返回 *BatchResult（added/duplicates 均为 0，并展示
373	// 当前已提交数据），无命中查询返回 *QueryResult 与空（非 nil）序列列表。
374	func TestProcessLineEmptySuccessesAreNonNullResults(t *testing.T) {
375		store := NewMetricStore()
376	
377		// 全新存储上的空批次：成功，0/0，序列列表为空但结果非 nil。
378		r := processOK(t, store, `[]`)
379		br, ok := r.(*BatchResult)
380		if !ok {
381			t.Fatalf("empty array result type = %T, want *BatchResult", r)
382		}
383		if br.Added != 0 || br.Duplicates != 0 || len(br.Series) != 0 {
384			t.Fatalf("empty batch on fresh store = %+v, want 0/0 and no series", br)
385		}
386	
387		// 全新存储上的查询：成功的查询结果，空序列列表（序列化为 [] 而不是缺省）。
388		r = processOK(t, store, `{"op":"query","name":"cpu","start":0,"end":3000}`)
389		qr, ok := r.(*QueryResult)
390		if !ok {
391			t.Fatalf("no-hit query result type = %T, want *QueryResult", r)
392		}
393		if qr.Status != "ok" || qr.Op != "query" || qr.Series == nil || len(qr.Series) != 0 {
394			t.Fatalf("no-hit query = %+v, want non-nil empty series list", qr)
395		}
396		if b, _ := json.Marshal(qr); string(b) != `{"status":"ok","op":"query","series":[]}` {
397			t.Fatalf("no-hit query JSON = %s, want empty series array", b)
398		}
399	
400		// 提交一个点后：空批次仍是 0/0 的成功结果，但展示当前已提交的 1 个点。
401		processSeedHostA(t, store)
402		r = processOK(t, store, `[]`)
403		br = r.(*BatchResult)
404		if br.Added != 0 || br.Duplicates != 0 {
405			t.Fatalf("empty batch counts = %d/%d, want 0/0", br.Added, br.Duplicates)
406		}
407		if len(br.Series) != 1 || len(br.Series[0].Points) != 1 ||
408			br.Series[0].Points[0] != (Point{Timestamp: 1000, Value: 2}) {
409			t.Fatalf("empty batch snapshot = %+v, want the committed (1000,2) point", br.Series)
410		}
411	
412		// 区间不命中是成功的空查询结果，区别于任何失败（失败时结果为 nil）。
413		r = processOK(t, store, `{"op":"query","name":"cpu","start":1001,"end":1999,"labels":{"host":"a"}}`)
414		qr = r.(*QueryResult)
415		if qr.Series == nil || len(qr.Series) != 0 {
416			t.Fatalf("miss query = %+v, want non-nil empty series list", qr)
417		}
418		r = processOK(t, store, `{"op":"query","name":"other","start":0,"end":3000}`)
419		if qr = r.(*QueryResult); len(qr.Series) != 0 {
420			t.Fatalf("unknown metric query = %+v, want empty series list", qr)
421		}
422	
423		// 对照：同样“没有数据可写入/可统计”的失败输入（空对象、null）必须是 nil，
424		// 不能被放松成成功的空结果。
425		if r, lerr := store.ProcessLine(`{}`); r != nil || lerr == nil {
426			t.Fatalf("empty object must fail with nil result, got r=%+v lerr=%+v", r, lerr)
427		}
428		if r, lerr := store.ProcessLine(`null`); r != nil || lerr == nil {
429			t.Fatalf("top-level null must fail with nil result, got r=%+v lerr=%+v", r, lerr)
430		}
431	}
432	
433	// 写入与查询经统一入口在同一存储上交替进行：成功结果各自保留 *BatchResult 与
434	// *QueryResult 类型，失败穿插其间不改变状态，恢复后新增与统计照常推进。
435	func TestProcessLineInterleavedWritesAndQueries(t *testing.T) {
436		store := NewMetricStore()
437	
438		// 正常写入：*BatchResult，added/duplicates 只统计本批。
439		r := processOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
440		br := r.(*BatchResult)
441		if br.Added != 1 || br.Duplicates != 0 || len(br.Series) != 1 {
442			t.Fatalf("first write = %+v, want added=1 one series", br)
443		}
444	
445		// 有命中查询：*QueryResult，1 个点、均值 2。
446		qr := processHostAQuery(t, store, 0, 3000)
447		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
448			t.Fatalf("first query = %+v, want count 1 average 2", qr.Series)
449		}
450	
451		// 失败写入与失败查询穿插：结果都是 nil，存储不进不退。
452		processFail(t, store, `[
453			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
454			{"name":"cpu","timestamp":1000,"value":9,"labels":{"host":"a"}}
455		]`)
456		processFail(t, store, `{"op":"query","name":"cpu","start":5000,"end":1000,"labels":{"host":"a"}}`)
457		processFail(t, store, `not json`)
458	
459		qr = processHostAQuery(t, store, 0, 3000)
460		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
461			t.Fatalf("state changed by interleaved failures: %+v", qr.Series)
462		}
463	
464		// 恢复：时间戳 2000、值 4 正常新增，随后查询得到两个点、均值 3。
465		r = processOK(t, store, `[{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}}]`)
466		br = r.(*BatchResult)
467		if br.Added != 1 || br.Duplicates != 0 || len(br.Series[0].Points) != 2 {
468			t.Fatalf("recovery write = %+v, want added=1 and two points", br)
469		}
470		qr = processHostAQuery(t, store, 0, 3000)
471		if len(qr.Series) != 1 || qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
472			t.Fatalf("query after recovery = %+v, want count 2 average 3", qr.Series)
473		}
474	
475		// 等值重提：仍是成功写入结果，新增 0、重复 1。
476		r = processOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2.0,"labels":{"host":"a"}}]`)
477		br = r.(*BatchResult)
478		if br.Added != 0 || br.Duplicates != 1 {
479			t.Fatalf("equal resubmit = %+v, want added=0 duplicates=1", br)
480		}
481	
482		// 空批次与无命中查询两类“空但成功”继续可用，且类型不与查询结果混淆。
483		r = processOK(t, store, `[]`)
484		if _, ok := r.(*BatchResult); !ok {
485			t.Fatalf("empty batch result type = %T, want *BatchResult", r)
486		}
487		r = processOK(t, store, `{"op":"query","name":"cpu","start":2001,"end":2999,"labels":{"host":"a"}}`)
488		if _, ok := r.(*QueryResult); !ok {
489			t.Fatalf("miss query result type = %T, want *QueryResult", r)
490		}
491	}
