1	package darksafe
2	
3	import (
4		"math/big"
5		"math/rand"
6		"testing"
7	)
8	
9	// 用 big.Int 参考实现核对窗口边界与窗口归属，覆盖接近 int64 上下界的区间。
10	func TestQueryWindowsReferenceDifferential(t *testing.T) {
11		cases := []struct {
12			start, end, step int64
13			ts               []int64
14		}{
15			{tsMinInt64, tsMaxInt64, tsMaxInt64, []int64{tsMinInt64, -2, -1, 0, 1, tsMaxInt64}},
16			{tsMinInt64, tsMaxInt64, 1, []int64{tsMinInt64, 0, tsMaxInt64}},
17			{-5, 4, 3, []int64{-5, -4, -1, 0, 1, 4}},
18			{1000, 3000, 1000, []int64{1000, 1999, 2000, 2999, 3000}},
19			{0, tsMaxInt64, tsMaxInt64, []int64{0, tsMaxInt64 - 1, tsMaxInt64}},
20			{tsMinInt64, tsMinInt64 + 10, 3, []int64{tsMinInt64, tsMinInt64 + 2, tsMinInt64 + 10}},
21			{tsMaxInt64 - 5, tsMaxInt64, 3, []int64{tsMaxInt64 - 5, tsMaxInt64 - 3, tsMaxInt64}},
22			{-10, 10, 7, []int64{-10, -4, -3, 3, 10}},
23		}
24		bStart := big.NewInt(0)
25		bEnd := big.NewInt(0)
26		bStep := big.NewInt(0)
27		bOne := big.NewInt(1)
28		for _, tc := range cases {
29			store := NewMetricStore()
30			line := "["
31			for i, ts := range tc.ts {
32				if i > 0 {
33					line += ","
34				}
35				line += sample("m", ts, float64(i+1), nil)
36			}
37			line += "]"
38			mustOK(t, store, line)
39			res := mustQueryWindows(t, store, queryWindowsAll("m", tc.start, tc.end, tc.step))
40	
41			// 参考分组：idx = (ts-start)/step（大整数整除），逐组累计点。
42			// idx 最大可达 2^64-1（step=1、跨整个 int64 区间），只能以 uint64 承载。
43			bStart.SetInt64(tc.start)
44			bEnd.SetInt64(tc.end)
45			bStep.SetInt64(tc.step)
46			groups := map[uint64][]int64{} // idx → timestamps
47			var order []uint64
48			for _, ts := range tc.ts {
49				if ts < tc.start || ts > tc.end {
50					continue
51				}
52				bTS := big.NewInt(ts)
53				idx := new(big.Int).Sub(bTS, bStart)
54				idx.Quo(idx, bStep)
55				if !idx.IsUint64() {
56					t.Fatalf("window idx overflows uint64: %v", idx)
57				}
58				k := idx.Uint64()
59				if _, ok := groups[k]; !ok {
60					order = append(order, k)
61				}
62				groups[k] = append(groups[k], ts)
63			}
64	
65			if len(res.Series) != 1 {
66				t.Fatalf("range [%d,%d] step %d: series = %+v", tc.start, tc.end, tc.step, res.Series)
67			}
68			got := res.Series[0].Windows
69			if len(got) != len(order) {
70				t.Fatalf("range [%d,%d] step %d: got %d windows %+v, want %d",
71					tc.start, tc.end, tc.step, len(got), got, len(order))
72			}
73			for i, k := range order {
74				// wStart = start + k*step；wEnd = min(wStart+step-1, end)。
75				ws := new(big.Int).Mul(new(big.Int).SetUint64(k), bStep)
76				ws.Add(ws, bStart)
77				we := new(big.Int).Add(ws, bStep)
78				we.Sub(we, bOne)
79				if we.Cmp(bEnd) > 0 {
80					we.Set(bEnd)
81				}
82				if !ws.IsInt64() || !we.IsInt64() {
83					t.Fatalf("window bounds overflow int64: [%v,%v]", ws, we)
84				}
85				if got[i].Start != ws.Int64() || got[i].End != we.Int64() {
86					t.Fatalf("window %d bounds = [%d,%d], want [%d,%d]",
87						k, got[i].Start, got[i].End, ws.Int64(), we.Int64())
88				}
89				if got[i].Count != len(groups[k]) {
90					t.Fatalf("window %d count = %d, want %d", k, got[i].Count, len(groups[k]))
91				}
92				// 检查窗口不倒置、不越界。
93				if got[i].Start > got[i].End || got[i].Start < tc.start || got[i].End > tc.end {
94					t.Fatalf("invalid window %+v within [%d,%d]", got[i], tc.start, tc.end)
95				}
96				// 平均 = (i+1) 的简单平均核对。
97				var sum float64
98				for _, ts := range groups[k] {
99					for j, x := range tc.ts {
100						if x == ts {
101							sum += float64(j + 1)
102						}
103					}
104				}
105				if got[i].Average != sum/float64(len(groups[k])) {
106					t.Fatalf("window %d average = %v, want %v", k, got[i].Average, sum/float64(len(groups[k])))
107				}
108			}
109		}
110	}
111	
112	// TestQueryWindowsRandomizedTiling 随机生成区间、步长与时间戳（含负数与接近
113	// int64 边界的值），直接核对输出窗口的归属、边界、截断与升序，不依赖参考分组。
114	func TestQueryWindowsRandomizedTiling(t *testing.T) {
